from pathlib import Path
import difflib,hashlib,json,stat
role=Path('docs/agent-work/changeo-gate0/developer/mercadopago')
rootbase=Path('docs/agent-work/changeo-implementation')
r3=json.loads((rootbase/'mercadopago-baseline.json').read_text())
required=['report.md','CHECKPOINT.md','notes.txt','logs/baseline-before.json','logs/seven-file.patch','logs/sources-manifest.json','logs/preservation-first.json','logs/document-first.json','logs/history-check.json','logs/web-evidence.json']+[f'logs/web-evidence-batch{i}.json' for i in range(2,10)]
errors=[]
artifacts=[]
for rel in required:
 p=role/rel
 if not p.is_file() or not p.stat().st_size:
  errors.append('missing/empty:'+str(p)); continue
 artifacts.append({'path':str(p),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
 if p.suffix=='.json': json.loads(p.read_text())
patch=[]
for rel in r3['allowed_deliverable_changes']:
 old=(rootbase/'mercadopago-baseline'/rel).read_text(); new=Path(rel).read_text()
 patch.extend(difflib.unified_diff(old.splitlines(keepends=True),new.splitlines(keepends=True),fromfile='pre-R3/'+rel,tofile=rel))
if (role/'logs/seven-file.patch').read_text()!=''.join(patch): errors.append('full seven-file patch stale')
for rel in ['report.md','CHECKPOINT.md','notes.txt']:
 if 'ready_for_review' not in (role/rel).read_text(): errors.append('status missing:'+rel)
root_observed=json.loads((rootbase/'logs/git-metadata-change.json').read_text())['current_git_metadata']
current=[]
for prior in root_observed:
 p=Path(prior['path']); s=p.stat()
 same=oct(s.st_mode)==prior['mode'] and s.st_size==prior['bytes']
 current.append({'path':str(p),'matches_root_observed_mode_size':same})
 if not same: errors.append('current git observation drift:'+str(p))
observed_paths={x['path'] for x in root_observed}
actual_paths={'.git'}|{str(x) for x in Path('.git').rglob('*')}
if observed_paths!=actual_paths: errors.append('current git inventory drift')
for match in __import__('re').finditer(r'\[[^\]]+\]\(([^)#]+)\)',(role/'report.md').read_text()):
 target=match[1]
 if not target.startswith('http') and not (role/target).is_file(): errors.append('report link:'+target)
print(json.dumps({'artifacts':artifacts,'artifact_count':len(artifacts),'full_patch_lines':len(patch),'actual_git_inventory_matches_root_observation':observed_paths==actual_paths,'git_mode_size_checks':current,'original_git_preservation':'EXCEPTION/UNVERIFIED; first exit1 retained; actor UNKNOWN; no approval inferred','errors':errors},indent=2))
raise SystemExit(1 if errors else 0)
